import{_ as s,o as n,c as e,a3 as o}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"Como Funciona","description":"","frontmatter":{"title":"Como Funciona"},"headers":[],"relativePath":"guia/03-como-funciona.md","filePath":"guia/03-como-funciona.md","lastUpdated":1787590468000}'),i={name:"guia/03-como-funciona.md"};function p(t,a,l,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="🔄-3-como-funciona" tabindex="-1">🔄 3. Como Funciona <a class="header-anchor" href="#🔄-3-como-funciona" aria-label="Permalink to &quot;🔄 3. Como Funciona&quot;">​</a></h1><p>O Angular não publica diretamente os arquivos de <code>src/</code>. Primeiro, o projeto precisa ser compilado com:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --configuration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span></span></code></pre></div><p>O build transforma o código TypeScript e demais recursos da aplicação em arquivos prontos para publicação.</p><p>O Firebase Hosting publica somente a pasta definida na propriedade <code>hosting.public</code> do arquivo <code>firebase.json</code>.</p><h3 id="fluxo" tabindex="-1">Fluxo <a class="header-anchor" href="#fluxo" aria-label="Permalink to &quot;Fluxo&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Código-fonte Angular</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>ng build --configuration production</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Pasta dist/</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Localização do index.html</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>firebase.json</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Firebase Hosting</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Aplicação publicada</span></span></code></pre></div><blockquote><p><strong>Regra de ouro:</strong> o valor de <code>hosting.public</code> deve apontar para a pasta que contém diretamente o <code>index.html</code> gerado pelo build.</p></blockquote><p>Em projetos Angular recentes, essa pasta pode ser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist/nome-do-projeto/browser</span></span></code></pre></div><p>ou, dependendo da configuração do projeto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist/nome-do-projeto</span></span></code></pre></div><p>Por isso, <strong>não presuma o caminho</strong>. Sempre verifique onde o Angular realmente gerou o <code>index.html</code>.</p>`,13)])])}const g=s(i,[["render",p]]);export{h as __pageData,g as default};
